'use strict';
// Question bank: business workspace templates, team roles, template content,
// search, creation and perspectives (course 2-0108, 22.1, chapters 10–15 and
// the review appendix). All questions are original. Format: curriculum/CONTENT.md.

module.exports = [
  // ------------------------------------------------------------ ws-types (templates, content)
  { id: 'bw-qc-types-001', domain: 'ws-types', q: 'An administrator wants to add the first workspace template, but Enterprise ▸ Document Templates ▸ Add Item does not list “Business Workspace”. What is the cause?', options: ['Business Workspace (subtype 848) is not a managed object type in Document Templates administration', 'No perspective exists for the type', 'The workspace type has no icon', 'The administrator lacks Delete permission on the volume'], answer: 0, explain: 'Workspace templates are built on the Document Templates module, which only offers its managed object types. Select subtype 848 under Configure Content Server Document Templates ▸ Managed object types.', guide: 'bw-document-template-settings' },
  { id: 'bw-qc-types-002', domain: 'ws-types', q: 'Which item type is a workspace template in Content Server?', options: ['A Folder with a category', 'A Business Workspace item (subtype 848) in the Document Templates volume', 'A Project template', 'A Workspace Type object in the Classifications volume'], answer: 1, explain: 'A workspace template is a Business Workspace item stored in the Document Templates volume; workspaces are copies of it.', guide: 'bw-create-template' },
  { id: 'bw-qc-types-003', domain: 'ws-types', q: 'Which two settings must you choose when adding a workspace template so that users can create workspaces from it in the right folder? (Choose two.)', options: ['The classification shared with the location folder', 'The perspective', 'The search slice', 'The workspace type'], answer: [0, 3], explain: 'The type links the template to its naming and location; the classification makes the template available in folders carrying the same classification. Perspectives and slices are configured separately.', guide: 'bw-create-template' },
  { id: 'bw-qc-types-004', domain: 'ws-types', q: 'A new workspace opens with an empty header in Smart View even though the perspective uses the default header. The template was created without a category. What is true?', options: ['The header only shows data from the business object', 'The header needs the Template Administrator to be filled', 'Categories are optional on templates; the header is empty for another reason', 'A category on the template is mandatory because the header and sidebar display workspace data from it'], answer: 3, explain: 'The course states that assigning a category to a workspace template is mandatory so that the Smart View header (and Classic sidebar) can be populated.', guide: 'bw-create-template' },
  { id: 'bw-qc-types-005', domain: 'ws-types', q: 'Why does OpenText recommend disabling category inheritance on workspace templates?', options: ['Workspace metadata would be copied onto every sub-item at creation, never refreshed, and it costs performance', 'Inheritance prevents workspaces from being named', 'Inheritance stops replacement tags from working', 'Inherited categories make workspaces read-only'], answer: 0, explain: 'With inheritance on, documents, folders and tasks receive a static copy of the workspace’s attributes, which is not updated when the workspace changes and bloats the database. Use child-item indexing instead.', guide: 'bw-create-template' },
  { id: 'bw-qc-types-006', domain: 'ws-types', q: 'How do you disable category inheritance on a workspace template in the Classic View?', options: ['Workspace type ▸ Advanced ▸ Inheritance', 'Template ▸ Properties ▸ Categories ▸ Edit Inheritance ▸ Disable Inheritance', 'Template ▸ Team Roles and Permissions ▸ Inheritance', 'Document Templates administration ▸ Wizard Settings'], answer: 1, explain: 'Edit Inheritance is the middle button on the template’s Categories tab; tick Disable Inheritance, Submit, then Apply.', guide: 'bw-create-template' },
  { id: 'bw-qc-types-007', domain: 'ws-types', q: 'A team copies the Document Templates sub-folder “Projects”, which contains three workspace templates, to create “Projects 2”. What do they find?', options: ['An error — folders in Document Templates cannot be copied', 'All three templates in the copy', 'The copied folder without the workspace templates', 'Shortcuts to the templates'], answer: 2, explain: 'When a folder containing a workspace template is copied, the template is not copied. Copy each template individually into the Document Templates volume.', guide: 'bw-create-template' },
  { id: 'bw-qc-types-008', domain: 'ws-types', q: 'Which statement about templates per workspace type is correct?', options: ['Templates are optional when the type has a location', 'Each type has exactly one template', 'A template can serve several workspace types', 'Usually one template per type, but several templates for the same type are allowed'], answer: 3, explain: 'Designers typically create one template per type and may add more for the same type when defaults or structure differ.', guide: 'bw-create-template' },
  { id: 'bw-qc-types-009', domain: 'ws-types', q: 'A task list in a template is named “Kick-off meeting”. After a year there are 600 identical task lists across workspaces. What should have been used?', options: ['A replacement tag in the name, such as <Category_CatID_AttrID />', 'A perspective rule', 'A different task list per user', 'Category inheritance'], answer: 0, explain: 'Replacement tags give each copy a name containing a value of its workspace, so tasks remain distinguishable.', guide: 'bw-template-content' },
  { id: 'bw-qc-types-010', domain: 'ws-types', q: 'Where does a designer look up the IDs needed for a replacement tag?', options: ['In Perspective Manager’s Code Editor', 'On the page shown by appending ?func=attributes.dump to the Content Server URL', 'In the Enterprise Data Flow Manager', 'On the workspace type’s General tab'], answer: 1, explain: 'The attributes dump lists category definitions with their IDs and attribute IDs.', guide: 'bw-template-content' },
  { id: 'bw-qc-types-011', domain: 'ws-types', q: 'Which two items are commonly named with replacement tags in a workspace template? (Choose two.)', options: ['Email folders', 'The Document Templates volume', 'Search regions', 'Task lists'], answer: [0, 3], explain: 'The course builds both a task list and an email folder whose names include category tags; tags are especially recommended for task lists.', guide: 'bw-template-content' },
  { id: 'bw-qc-types-012', domain: 'ws-types', q: 'A folder in a template should collect product specifications that users will filter by spec attributes. What is an appropriate configuration?', options: ['Make it a second workspace type', 'Enable category inheritance on the whole template', 'Create a forum instead', 'Attach an additional category to that folder in the template'], answer: 3, explain: 'Folders in a template may carry an optional category of their own, which can then be used for facets and filtering.', guide: 'bw-template-content' },
  { id: 'bw-qc-types-013', domain: 'ws-types', q: 'An attribute used in a task list’s replacement tag is changed in the workspace six months after creation. What happens to the task list’s name?', options: ['It stays as it was when the workspace was created', 'It reverts to the raw tag', 'It updates at the next re-index', 'It updates immediately'], answer: 0, explain: 'Replacement tags in item names are resolved once, at creation.', guide: 'bw-template-content' },
  { id: 'bw-qc-types-014', domain: 'ws-types', q: 'Which three kinds of content can a workspace template contain, according to the course? (Choose three.)', options: ['Folders', 'Email folders', 'Task lists', 'Search regions'], answer: [0, 1, 2], explain: 'Templates hold folders, email folders, documents, task lists, forums and similar items. Search regions belong to the search engine configuration.', guide: 'bw-template-content' },
  { id: 'bw-qc-types-015', domain: 'ws-types', q: 'In the capstone, a designer builds the configuration in this order. Which step is out of place? Category → classification → template → location folder → workspace type → roles.', options: ['Roles should come before the template', 'The classification should come last', 'The template comes before the workspace type it must reference', 'The category comes too early'], answer: 2, explain: 'A template is created with a workspace type selected, so the type (and the location it points to) must exist first.', guide: 'bw-capstone' },
  { id: 'bw-qc-types-016', domain: 'ws-types', q: 'In the Add: Business Workspace page for a template, what is the Name field used for?', options: ['The email alias of the email folder', 'The perspective title', 'The name of every workspace created from it', 'The label users see when choosing the template in the Add menu'], answer: 3, explain: 'The template name is shown when creating; each workspace’s own name comes from the workspace type’s name pattern.', guide: 'bw-create-template' },

  // ------------------------------------------------------------ ba-ws-types
  { id: 'bw-qc-batypes-001', domain: 'ba-ws-types', q: 'In Configure Content Server Document Templates, what does “Apply new create date to sub-items” do when enabled?', options: ['Sets each sub-item’s creation date to the current date when it is created from the template', 'Updates the modify date of the template', 'Adds a date attribute to the category', 'Re-dates existing workspaces nightly'], answer: 0, explain: 'Enabled, sub-items get the current system date (and, with Records Management, record and status dates). Disabled — the default — they keep the template items’ dates.', guide: 'bw-document-template-settings' },
  { id: 'bw-qc-batypes-002', domain: 'ba-ws-types', q: 'Which items are NOT affected by “Apply new create date to sub-items”?', options: ['Workflows', 'Tasks and task lists', 'Documents', 'Folders'], answer: 1, explain: 'The course notes that tasks and task lists are not affected by this setting.', guide: 'bw-document-template-settings' },
  { id: 'bw-qc-batypes-003', domain: 'ba-ws-types', q: 'Which three choices does the Classification inheritance setting of Document Templates offer? (Choose three.)', options: ['Inherit classification of the nearest ancestor node', 'Do not inherit classifications of ancestor nodes', 'Inherit classification from the workspace type', 'Inherit classification of the direct parent node'], answer: [0, 1, 3], explain: 'The setting decides how templates inherit classifications from the folder hierarchy; workspace types do not carry classifications to inherit.', guide: 'bw-document-template-settings' },
  { id: 'bw-qc-batypes-004', domain: 'ba-ws-types', q: 'What does “Inherit RM classification from template” control?', options: ['Whether workspaces become records', 'Whether the template is declared a record', 'Whether retention starts at creation', 'Whether sub-items take the Records Management classification of the template rather than of the destination'], answer: 3, explain: 'On: sub-items use the template’s RM classification. Off: they inherit from the destination.', guide: 'bw-document-template-settings' },
  { id: 'bw-qc-batypes-005', domain: 'ba-ws-types', q: 'Which two are Wizard Settings conditions under which the Document Templates wizard can be enabled? (Choose two.)', options: ['If the perspective has tabs', 'If a document type is available', 'If classifications are inherited', 'If the user is a Team Lead'], answer: [1, 2], explain: 'Enable Wizard offers: if a document type is available, if categories are inherited, if classifications are inherited, or always.', guide: 'bw-document-template-settings' },
  { id: 'bw-qc-batypes-006', domain: 'ba-ws-types', q: 'What does the “Attribute merging” option of the Document Templates wizard do?', options: ['Merges perspectives', 'Merges attribute values from the template with those of the destination', 'Merges two categories into one', 'Merges workspaces with the same name'], answer: 1, explain: 'It lets attribute values from the document template and the destination be combined.', guide: 'bw-document-template-settings' },
  { id: 'bw-qc-batypes-007', domain: 'ba-ws-types', q: 'An organisation wants newly created documents from templates to open straight in their editor. Which setting does this?', options: ['Default classification', 'Category step', 'Edit document after creation', 'Template selection'], answer: 2, explain: '“Edit document after creation (either created using wizard or Smart View dialog)” opens the new document in an editor.', guide: 'bw-document-template-settings' },
  { id: 'bw-qc-batypes-008', domain: 'ba-ws-types', q: 'The template and the workspace type’s location folder must share which object?', options: ['A slice', 'A perspective', 'An owner group', 'A classification'], answer: 3, explain: 'The template classification on the location folder is how the template is offered there.', guide: 'bw-document-template-settings' },
  { id: 'bw-qc-batypes-009', domain: 'ba-ws-types', q: 'Which approach does the course recommend for making documents inside workspaces findable by workspace attributes?', options: ['Indexing of category attributes on child items, set on the workspace type', 'Adding the workspace category to each folder', 'A facet per workspace', 'Category inheritance from the template'], answer: 0, explain: 'Indexing keeps the data current in the index without copying it into every item; inheritance copies static metadata and hurts performance.', guide: 'bw-search-config' },
  { id: 'bw-qc-batypes-010', domain: 'ba-ws-types', q: 'Which two statements about Classic View content in a workspace template are true? (Choose two.)', options: ['A Related Business Workspaces folder can be added to show related workspaces', 'Existing folders can be moved or copied into a workspace template', 'Templates may not contain documents', 'Each folder must have the workspace category'], answer: [0, 1], explain: 'Classic templates can include a Related Business Workspaces folder, and move/copy support lets you migrate existing content into workspaces and templates. Documents are allowed and folder categories are optional.', guide: 'bw-template-content' },
  { id: 'bw-qc-batypes-011', domain: 'ba-ws-types', q: 'When you add a forum to a workspace template, which settings are offered on the Forum Settings page?', options: ['The slice and the region', 'The rule and the layout', 'A header text, whether to display it in all views, and moderators', 'The email alias and content storage'], answer: 2, explain: 'After Create, Forum Settings lets you show a header in all views, type the header and choose moderators.', guide: 'bw-template-content' },
  { id: 'bw-qc-batypes-012', domain: 'ba-ws-types', q: 'In a replacement tag <Category_884213_3 />, what is 884213?', options: ['The workspace type ID', 'The template ID', 'The attribute number', 'The category’s node ID'], answer: 3, explain: 'The format is <Category_CatID_AttrID />: category ID, underscore, attribute ID.', guide: 'bw-template-content' },
  { id: 'bw-qc-batypes-013', domain: 'ba-ws-types', q: 'Where is the classification tree that holds the template “document types” selected for all document templates?', options: ['In Configure Content Server Document Templates ▸ Classification tree for document types', 'In Perspective Manager', 'In the Classifications volume’s properties', 'On each workspace type'], answer: 0, explain: 'It is a system-wide Document Types setting of the Document Templates module.', guide: 'bw-document-template-settings' },
  { id: 'bw-qc-batypes-014', domain: 'ba-ws-types', q: 'Which statement about the Document Templates settings is correct?', options: ['They are configured separately on each template', 'They are system-wide and apply to all document templates', 'They apply only to Smart View', 'They are stored in the perspective'], answer: 1, explain: 'The Configure Content Server Document Templates page sets behaviour for every template on the server.', guide: 'bw-document-template-settings' },

  // ------------------------------------------------------------ ws-roles
  { id: 'bw-qc-roles-001', domain: 'ws-roles', q: 'Which role is added automatically to every workspace template?', options: ['Reader', 'Team Lead', 'Template Administrator', 'Workspace Owner'], answer: 2, explain: 'The Template Administrator role exists on every template to control who may create and change it.', guide: 'bw-team-roles' },
  { id: 'bw-qc-roles-002', domain: 'ws-roles', q: 'A user is in the Template Administrator role of the Supplier template. What access does that give them in the 400 Supplier workspaces?', options: ['Team Lead rights in all of them', 'Full control in all of them', 'Read access in all of them', 'None through that role — it is not copied to workspaces'], answer: 3, explain: 'The Template Administrator role is not copied to workspaces created from the template.', guide: 'bw-team-roles' },
  { id: 'bw-qc-roles-003', domain: 'ws-roles', q: 'How is the Team Lead role shown on the Team Roles and Permissions page?', options: ['With a red flag', 'With a key icon', 'At the bottom of the list', 'In bold'], answer: 0, explain: 'The Team Lead role carries a red flag icon.', guide: 'bw-team-roles' },
  { id: 'bw-qc-roles-004', domain: 'ws-roles', q: 'A designer adds the roles Coordinator, then Planner, then Observer to a new template and changes nothing else. Which is the Team Lead?', options: ['Planner', 'Coordinator', 'None until one is set', 'Observer'], answer: 1, explain: 'By default the first role added besides the Template Administrator becomes the Team Lead; Set as Team Lead can change it.', guide: 'bw-team-roles' },
  { id: 'bw-qc-roles-005', domain: 'ws-roles', q: 'Which two statements about team participants are true? (Choose two.)', options: ['A participant inherits the permissions of the roles they are added to', 'A role may contain only one participant', 'Participants must be added on the template', 'A participant can be a user or a group'], answer: [0, 3], explain: 'Users and groups can be participants, can hold several roles, and receive the role permissions. Participants are usually added on the workspace, not the template.', guide: 'bw-team-roles' },
  { id: 'bw-qc-roles-006', domain: 'ws-roles', q: 'Where are team participants normally assigned?', options: ['On the workspace type', 'On the location folder', 'On the template for every workspace', 'On each individual business workspace'], answer: 3, explain: 'Roles are defined on the template; team members differ per workspace and are added there.', guide: 'bw-team-roles' },
  { id: 'bw-qc-roles-007', domain: 'ws-roles', q: 'In Smart View, where does a team lead add a colleague to a role of an existing workspace?', options: ['In the Team widget of the workspace', 'In Perspective Manager', 'In the Document Templates volume', 'In the slice permissions'], answer: 0, explain: 'Team roles and participants can be managed directly in the workspace’s Team widget.', guide: 'bw-creation-wizard' },
  { id: 'bw-qc-roles-008', domain: 'ws-roles', q: 'A workspace is moved from a plain folder into another business workspace that has team roles. “Always inherit the permissions from target destination” is OFF. What happens to its roles? (Choose two.)', options: ['Inherited team roles and permissions are removed', 'Roles assigned directly to the workspace remain', 'The destination’s roles and participants are copied in', 'All roles are deleted, including direct ones'], answer: [0, 1], explain: 'On a move, inherited roles go and direct roles stay; destination roles are copied only when the “always inherit” option is on.', guide: 'bw-team-roles' },
  { id: 'bw-qc-roles-009', domain: 'ws-roles', q: 'Which permission set did the course give a sales-rep style role that should add documents and update metadata but not delete?', options: ['Delete', 'Edit Permissions', 'Add Items and Edit Attributes', 'See only'], answer: 2, explain: 'A contributor role typically gets Add Items and Edit Attributes; the lead role gets Edit Permissions.', guide: 'bw-team-roles' },
  { id: 'bw-qc-roles-010', domain: 'ws-roles', q: 'In an Employee/Absence Case hierarchy with role mapping, which statement is true?', options: ['Mapping copies all parent documents into the child', 'Mapping removes the child roles', 'Absence Case members automatically see the Employee workspace', 'Mapped Employee roles can work in the Absence Case workspace with the mapped child role’s rights'], answer: 3, explain: 'A mapped parent role replaces the child role in the child workspace with that role’s access; child roles do not gain parent access.', guide: 'bw-workspace-hierarchies' },
  { id: 'bw-qc-roles-011', domain: 'ws-roles', q: 'What is the main benefit of role mapping in workspace hierarchies?', options: ['Fewer roles to maintain, since parent teams reach child workspaces', 'Faster search', 'Automatic email-enabling', 'No need for templates'], answer: 0, explain: 'Parent roles act as child roles, so the team is maintained once at the parent level.', guide: 'bw-workspace-hierarchies' },
  { id: 'bw-qc-roles-012', domain: 'ws-roles', q: 'Which use case does the course give for workspace hierarchies?', options: ['Landing pages', 'Case management, such as employee files', 'Search slices', 'Transport packages'], answer: 1, explain: 'Hierarchies suit case management: a parent (employee) workspace holding child case workspaces.', guide: 'bw-workspace-hierarchies' },
  { id: 'bw-qc-roles-013', domain: 'ws-roles', q: 'When is it appropriate to add participants to a normal role on the template itself?', options: ['Always — it saves time per workspace', 'Never — the dialog does not allow it', 'Only for a group that genuinely belongs in every workspace created from it', 'Only for the Template Administrator role'], answer: 2, explain: 'Template participants are copied to every workspace; use that only for groups that truly belong everywhere. Named individuals belong on the workspace.', guide: 'bw-team-roles' },

  // ------------------------------------------------------------ ba-roles
  { id: 'bw-qc-baroles-001', domain: 'ba-roles', q: 'Which menu entry opens the page where roles are added to a workspace template in the Classic View?', options: ['Functions ▸ Permissions ▸ Grant Access', 'Functions ▸ Properties ▸ Specific', 'Functions ▸ Team Participants', 'Functions ▸ Team Roles and Permissions'], answer: 3, explain: 'Team Roles and Permissions holds Add Role and the role permissions; Team Participants adds people to roles.', guide: 'bw-team-roles' },
  { id: 'bw-qc-baroles-002', domain: 'ba-roles', q: 'Under which condition can the Team Lead role be deleted from a template?', options: ['When it is the only role in the list', 'When it has no permissions', 'When the template has no content', 'Never'], answer: 0, explain: 'The Team Lead role can be deleted only if it is the only role.', guide: 'bw-team-roles' },
  { id: 'bw-qc-baroles-003', domain: 'ba-roles', q: 'A workspace is created inside an existing business workspace. The new workspace receives the destination’s team roles and participants too. Which template setting caused this?', options: ['Classification inheritance', 'Merge with creation location (template Specific tab)', 'Always inherit the permissions from target destination', 'Apply new create date to sub-items'], answer: 1, explain: 'Copying destination roles at creation applies only when merging with the creation location is enabled.', guide: 'bw-team-roles' },
  { id: 'bw-qc-baroles-004', domain: 'ba-roles', q: 'Where is “Always inherit the permissions from target destination” configured?', options: ['On the workspace type’s Advanced tab', 'On the workspace template’s Specific tab', 'Content Server Administration ▸ Core System – Feature Administration ▸ Access Control', 'In Perspective Manager rules'], answer: 2, explain: 'It is a system-wide access-control feature setting that affects moves.', guide: 'bw-team-roles' },
  { id: 'bw-qc-baroles-005', domain: 'ba-roles', q: 'Which two events trigger group replacement defined on a template’s Specific tab? (Choose two.)', options: ['Opening the workspace', 'Adding a document', 'Creating the workspace', 'Updating or clearing the workspace’s categories'], answer: [2, 3], explain: 'Group replacement runs at creation and again when categories are updated or cleared.', guide: 'bw-team-roles' },
  { id: 'bw-qc-baroles-006', domain: 'ba-roles', q: 'In the group replacement table on a template’s Specific tab, what does the Target Group column define?', options: ['The name of the group to be generated', 'The Team Lead', 'The slice owner', 'The group that may edit the template'], answer: 0, explain: 'Target Group names the generated group that replaces the template’s restricting group.', guide: 'bw-team-roles' },
  { id: 'bw-qc-baroles-007', domain: 'ba-roles', q: 'Where is it defined which business workspaces may be created inside another workspace?', options: ['In the Enterprise Search Manager', 'In the document templates (Workspace Hierarchies), identifying workspaces by classification', 'In the location folder’s permissions', 'In Perspective Manager'], answer: 1, explain: 'The hierarchy mechanism lives in the templates and identifies workspace kinds by their classifications.', guide: 'bw-workspace-hierarchies' },
  { id: 'bw-qc-baroles-008', domain: 'ba-roles', q: 'What is a prerequisite before configuring a workspace hierarchy with role mapping?', options: ['A slice exists for each type', 'The Template Administrator is empty', 'Both parent and child workspace types are fully configured, including their templates and roles', 'Child-item indexing is disabled'], answer: 2, explain: 'You map roles that must already exist on fully configured parent and child templates.', guide: 'bw-workspace-hierarchies' },
  { id: 'bw-qc-baroles-009', domain: 'ba-roles', q: 'A business administrator gives a broad “Template Maintainers” group full control by adding it to the Team Lead role of a template. What is the consequence?', options: ['The group can only edit the template', 'The group becomes Template Administrator', 'None — template roles are never copied', 'The group becomes Team Lead in every workspace created afterwards'], answer: 3, explain: 'Participants of normal roles on the template are copied into every new workspace. Maintainers belong in the Template Administrator role, which is not copied.', guide: 'bw-team-roles' },
  { id: 'bw-qc-baroles-010', domain: 'ba-roles', q: 'Which two settings influence how roles and participants are handled when workspaces are created and moved? (Choose two.)', options: ['Run in test mode without indexing', 'Merge with creation location', 'Always inherit the permissions from target destination', 'Hide empty fields'], answer: [1, 2], explain: 'The template’s merge option governs creation inside another workspace; the Access Control option governs moves. The others are widget and indexing settings.', guide: 'bw-team-roles' },
  { id: 'bw-qc-baroles-011', domain: 'ba-roles', q: 'How do you assign the Sys Admin group to the Template Administrator role of a template?', options: ['Perspective Manager ▸ Rules ▸ Group', 'Template ▸ Team Participants ▸ Find & Add ▸ choose Template Administrator for the group ▸ Submit', 'Template ▸ Permissions ▸ Grant Access ▸ Full Control', 'Workspace type ▸ Advanced ▸ Administrators'], answer: 1, explain: 'Participants of template roles, including Template Administrator, are added on the Team Participants page.', guide: 'bw-team-roles' },
  { id: 'bw-qc-baroles-012', domain: 'ba-roles', q: 'With role mapping, which role carries the access rights in the child workspace after mapping?', options: ['Read-only for everyone', 'The parent role’s own rights from the parent', 'The child role’s access rights, now held by the mapped parent role', 'Full control for everyone'], answer: 2, explain: 'The child role is replaced by the mapped parent role, with all the access rights of the child role.', guide: 'bw-workspace-hierarchies' },

  // ------------------------------------------------------------ ws-using (creation, search use, perspectives use)
  { id: 'bw-qc-using-001', domain: 'ws-using', q: 'In what order does the Classic View Business Workspace wizard present its pages?', options: ['Metadata → Type → Classifications', 'Classifications → Metadata → Type', 'Type → Classifications → Metadata', 'Type → Metadata → Classifications'], answer: 3, explain: 'Type (template, generated name), Metadata (category attributes), Classifications, then Finish.', guide: 'bw-creation-wizard' },
  { id: 'bw-qc-using-002', domain: 'ws-using', q: 'On the Metadata page of the wizard, a user clicks Next with a required attribute empty. What happens?', options: ['An error message stops the wizard until the field is filled', 'The attribute is removed from the category', 'The default template value is used silently', 'The workspace is created without the value'], answer: 0, explain: 'Required attributes must be filled before the wizard continues.', guide: 'bw-creation-wizard' },
  { id: 'bw-qc-using-003', domain: 'ws-using', q: 'Which two ways does Smart View offer to start creating a workspace from a location (root) folder? (Choose two.)', options: ['The + (Add item) menu', 'The Create Business Workspace icon next to Favorites', 'The Properties panel', 'The search box'], answer: [0, 1], explain: 'Both entry points open the creation form for the template offered in that folder.', guide: 'bw-creation-wizard' },
  { id: 'bw-qc-using-004', domain: 'ws-using', q: 'Why should end users normally not change the classification on the wizard’s Type or Classifications page?', options: ['Classifications are required for email', 'Changing them renames the workspace', 'Classifications decide which templates are offered and are set by design through the template', 'Classifications delete documents'], answer: 2, explain: 'The template supplies the intended classification; additional ones are possible if permitted, but users generally should not change them.', guide: 'bw-creation-wizard' },
  { id: 'bw-qc-using-005', domain: 'ws-using', q: 'A workflow must create a project workspace and later file a document into it. Which two workflow elements support this? (Choose two.)', options: ['A Perspective step', 'A Slice step', 'A Create Workspace step that uses a template and mapped attribute values', 'An Item Reference attribute holding the new workspace for later steps'], answer: [2, 3], explain: 'The Create Workspace step needs a template and mapped attributes; storing the result in an Item Reference attribute lets later steps such as an Item Handler use it.', guide: 'bw-creation-wizard' },
  { id: 'bw-qc-using-006', domain: 'ws-using', q: 'A new workspace was created from a template whose email folder has no address. What does a team member do so customers can mail into it?', options: ['Use Functions ▸ Email Enable on the folder and set the Email Alias', 'Add the folder to a slice', 'Change the folder’s category', 'Ask for a new template'], answer: 0, explain: 'Email folders are email-enabled per workspace via eLink, which assigns the alias.', guide: 'bw-creation-wizard' },
  { id: 'bw-qc-using-007', domain: 'ws-using', q: 'On the Enable eLink page, what does the “Content Stored” option decide?', options: ['The email server address', 'Whether only the message body is stored when an email is added', 'Which users may send mail', 'The folder’s retention'], answer: 1, explain: 'It controls what part of an emailed item is stored in the container.', guide: 'bw-creation-wizard' },
  { id: 'bw-qc-using-008', domain: 'ws-using', q: 'After changing the Risk Class of a supplier workspace, a buyer wants to see the activity message in the Classic View. Where?', options: ['In the slice', 'In the Recycle Bin', 'In the sidebar’s Pulse From Here, or Personal ▸ Pulse', 'In the Document Templates volume'], answer: 2, explain: 'Configured activity rules post attribute changes to Pulse; the Classic sidebar shows Pulse From Here.', guide: 'bw-creation-wizard' },
  { id: 'bw-qc-using-009', domain: 'ws-using', q: 'A user picks the “Supplier” slice in the Smart View search box. What does that do?', options: ['Opens the Supplier template', 'Creates a Supplier workspace', 'Shows the Supplier perspective', 'Restricts the search to items of the Supplier workspace type'], answer: 3, explain: 'A slice built on XECMWkspLinkRefTypeID scopes the search to that workspace type.', guide: 'bw-search-config' },
  { id: 'bw-qc-using-010', domain: 'ws-using', q: 'Which three places in the Classic View offer business workspace simple searches? (Choose three.)', options: ['The Recycle Bin', 'The global menu Business Workspaces ▸ Search', 'The target browse window when copying or moving', 'Searching for the related workspace when adding a relationship'], answer: [1, 2, 3], explain: 'Simple searches (Custom Views) appear in those three places; they are not used in the Recycle Bin.', guide: 'bw-custom-view-search' },
  { id: 'bw-qc-using-011', domain: 'ws-using', q: 'A user opens a Supplier workspace in Smart View. Which widgets are on the Overview tab of an unchanged new workspace perspective?', options: ['Node Browsing Table', 'Team, Metadata and Discussion', 'Workspaces and Configuration Volume', 'Favorites and Recently Accessed'], answer: 1, explain: 'The sample layout has a Header, an Overview tab (Team, Metadata, Discussion) and a Documents tab (Node Browsing Table).', guide: 'bw-perspectives' },
  { id: 'bw-qc-using-012', domain: 'ws-using', q: 'In a workspace’s Team widget, which roles are listed besides those with members?', options: ['Roles from other workspaces', 'None', 'Roles that have no members', 'Only the Template Administrator'], answer: 2, explain: 'The Team widget shows the team members and the roles that have no members yet.', guide: 'bw-perspective-widgets' },
  { id: 'bw-qc-using-013', domain: 'ws-using', q: 'A search for a customer number finds the customer workspace but none of the documents inside it. Child-item indexing is not enabled. Which change fixes this for existing and new documents? (Choose two.)', options: ['Enable category inheritance on the template', 'Add the number to each document title', 'Enable indexing of category attributes on child items for the workspace type', 'Schedule the workspace type for re-indexing'], answer: [2, 3], explain: 'Indexing on child items covers new items; Schedule for Re-indexing updates existing ones. Inheritance is the discouraged alternative.', guide: 'bw-search-config' },
  { id: 'bw-qc-using-014', domain: 'ws-using', q: 'Workspaces created in the root folder “Customer” end up in “Customer ▸ National”. Which configuration explains it?', options: ['The workspace type’s location with an attribute-based sub-folder, also used for manual creation', 'Category inheritance', 'The Team Lead role', 'The perspective rule'], answer: 0, explain: 'When the type’s location settings also apply to manual creation, an attribute value such as Account Level can file the workspace into a sub-folder.', guide: 'bw-creation-wizard' },
  { id: 'bw-qc-using-015', domain: 'ws-using', q: 'After the capstone, which quick test best proves the whole configuration?', options: ['Restart the server', 'Create a workspace and check name, location, content, team, search and Smart View layout', 'Read the template’s properties', 'Count the categories'], answer: 1, explain: 'A fresh workspace exercises every configuration object at once.', guide: 'bw-capstone' },

  // ------------------------------------------------------------ ba-search
  { id: 'bw-qc-search-001', domain: 'ba-search', q: 'Which value replaces n in the slice query XECMWkspLinkRefTypeID:n?', options: ['The node ID of the template', 'The category ID', 'The ID_CFG value shown in the workspace type’s URL', 'The classification ID'], answer: 2, explain: 'The workspace type’s configuration ID appears as ID_CFG at the end of its URL (e.g. ReferenceTypeEdit&ID_CFG=4).', guide: 'bw-search-config' },
  { id: 'bw-qc-search-002', domain: 'ba-search', q: 'In Advanced Search, which Full Text “Look For” option is used to enter XECMWkspLinkRefTypeID:4?', options: ['Any words', 'All words', 'Exact phrase', 'Complex Query'], answer: 3, explain: 'Region queries are entered as a Complex Query.', guide: 'bw-search-config' },
  { id: 'bw-qc-search-003', domain: 'ba-search', q: 'What should you do before saving the XECMWkspLinkRefTypeID query as a slice?', options: ['Run the search and confirm the results are the expected workspaces', 'Re-index the whole system', 'Delete the template', 'Disable the region'], answer: 0, explain: 'Test the query first; fix it and retest if the results are wrong.', guide: 'bw-search-config' },
  { id: 'bw-qc-search-004', domain: 'ba-search', q: 'Where is a saved slice stored?', options: ['In the workspace type', 'In the Slice Folder', 'In the Document Templates volume', 'In the Perspectives volume'], answer: 1, explain: 'Save as Slice stores it in the Slice Folder, where you then set its permissions.', guide: 'bw-search-config' },
  { id: 'bw-qc-search-005', domain: 'ba-search', q: 'When is the XECMWkspLinkRefTypeID region created?', options: ['When Perspective Manager is opened', 'When an administrator adds it manually', 'Automatically, when the first business workspace (a template counts) is created and indexed', 'When the first slice is saved'], answer: 2, explain: 'The module creates its regions automatically; a template is technically a workspace, so the region usually exists once a template exists.', guide: 'bw-search-config' },
  { id: 'bw-qc-search-006', domain: 'ba-search', q: 'Which path leads to the setting that makes XECMWkspLinkRefTypeID queryable?', options: ['Document Templates administration ▸ Managed object types', 'Perspectives Administration ▸ Rules', 'Workspace type ▸ Advanced ▸ Indexing Settings', 'System Object Volume ▸ Enterprise Data Source Folder ▸ Enterprise Search Manager ▸ Properties ▸ Regions'], answer: 3, explain: 'Regions are configured on the Enterprise Search Manager; tick Queryable and Update.', guide: 'bw-search-config' },
  { id: 'bw-qc-search-007', domain: 'ba-search', q: 'Which three item types are already selected as indexable subtypes when you open Configure indexable subtypes for a workspace type in 22.1? (Choose three.)', options: ['Task List', 'Business Workspace', 'Document', 'Email'], answer: [1, 2, 3], explain: 'Business Workspace, Document and Email are preselected; Task List, Folder, Forum and others are added as needed.', guide: 'bw-search-config' },
  { id: 'bw-qc-search-008', domain: 'ba-search', q: 'An administrator enables child-item indexing for a workspace type. What does the Workspace Types list show for that type afterwards?', options: ['Disabled', 're-indexing required', 'Locked', 'Transport pending'], answer: 1, explain: 'Existing items must be re-indexed; the status flags it until Schedule for Re-indexing is run.', guide: 'bw-search-config' },
  { id: 'bw-qc-search-009', domain: 'ba-search', q: 'What is the purpose of “Run in test mode without indexing” on the Schedule Workspace Items for Re-indexing page?', options: ['To delete the index', 'To re-index only templates', 'To see a summary of what would be processed without indexing anything', 'To index only test documents'], answer: 2, explain: 'The test run produces a Summary of last action; then you clear the box and start the real run.', guide: 'bw-search-config' },
  { id: 'bw-qc-search-010', domain: 'ba-search', q: 'Where do you monitor the progress of a scheduled workspace re-indexing?', options: ['Team Participants', 'The Slice Folder', 'Perspective Manager', 'Enterprise Data Flow Manager ▸ Interchange Pools'], answer: 3, explain: 'The iPools show Status, Pending, Processed and Quarantined counts; refresh the page to follow progress.', guide: 'bw-search-config' },
  { id: 'bw-qc-search-011', domain: 'ba-search', q: 'Which two settings are typical when building the saved query behind a workspace simple search? (Choose two.)', options: ['Options ▸ Hide empty fields', 'System Attributes ▸ Content Type = Business Workspace', 'Slices ▸ the workspace type’s slice', 'Full Text ▸ Exact phrase = the workspace name'], answer: [1, 2], explain: 'Restricting to Business Workspace items and the type’s slice, then adding the workspace category, is the standard recipe.', guide: 'bw-custom-view-search' },
  { id: 'bw-qc-search-012', domain: 'ba-search', q: 'Which function turns a saved search query into a compact simple-search form?', options: ['Save as Slice', 'Make Custom View Search', 'Schedule for Re-indexing', 'Make System Search Form'], answer: 1, explain: 'Make Custom View Search lets you tick which fields to show and give the form a (multilingual) title.', guide: 'bw-custom-view-search' },
  { id: 'bw-qc-search-013', domain: 'ba-search', q: 'Which statement about child-item indexing of workspace attributes is true?', options: ['It replaces slices', 'It copies the category onto child items', 'It adds the workspace’s category attributes to the index data of child items and nested workspaces', 'It applies retroactively without re-indexing'], answer: 2, explain: 'The attributes become supplementary indexed metadata for children; existing items still need re-indexing.', guide: 'bw-search-config' },

  // ------------------------------------------------------------ ba-smart (Perspective Manager)
  { id: 'bw-qc-smart-001', domain: 'ba-smart', q: 'Perspective Manager is launched from a workspace type’s “Manage Perspectives for this workspace type” link. Which option is missing compared with launching it from the administration pages?', options: ['The Widget Library', 'The Create button', 'The Rules tab', 'The Layout option'], answer: 3, explain: 'Business workspaces already have a defined layout, so the type-specific launch omits Layout. The admin-page launch has full functionality.', guide: 'bw-perspectives' },
  { id: 'bw-qc-smart-002', domain: 'ba-smart', q: 'Which rule types can a workspace perspective rule evaluate? (Choose three.)', options: ['Document MIME type', 'Workspace Type', 'Workspace Template', 'Mobile Device'], answer: [1, 2, 3], explain: 'Rule types include Group, Mobile Device, User, Workspace Template and Workspace Type; MIME type is not one of them.', guide: 'bw-perspectives' },
  { id: 'bw-qc-smart-003', domain: 'ba-smart', q: 'How are the rules of a perspective evaluated?', options: ['Bottom to top', 'Top to bottom', 'Randomly', 'Only the last rule counts'], answer: 1, explain: 'Rules are evaluated in order from top to bottom, joined by AND or OR.', guide: 'bw-perspectives' },
  { id: 'bw-qc-smart-004', domain: 'ba-smart', q: 'An administrator removes all rules from a workspace perspective and saves it. Who sees it?', options: ['Nobody', 'Only members of the Template Administrator role', 'All users on all devices', 'Only mobile users'], answer: 2, explain: 'With no rule the perspective applies universally — usually not what you want.', guide: 'bw-perspectives' },
  { id: 'bw-qc-smart-005', domain: 'ba-smart', q: 'A designer created a perspective from the workspace type page, clicked Create and closed Perspective Manager, but the workspaces still show the old layout. What did they most likely forget?', options: ['Re-indexing', 'Adding a slice', 'Email-enabling the folder', 'Save Changes on the workspace type page'], answer: 3, explain: 'The course stresses that the workspace type page must also be saved; it is the most commonly forgotten step.', guide: 'bw-perspectives' },
  { id: 'bw-qc-smart-006', domain: 'ba-smart', q: 'Which placeholder shows the name of the workspace type in the Header widget?', options: ['{business_properties.workspace_type_name}', '{categories.workspace_type}', '{name}', '{type_name}'], answer: 0, explain: 'Business properties need the business_properties prefix; {type_name} returns the item type (Business Workspace).', guide: 'bw-perspective-widgets' },
  { id: 'bw-qc-smart-007', domain: 'ba-smart', q: 'The Header title should read “S-0042 – Northwind Metals” from two attributes. What is the right approach?', options: ['Keep {name}', 'Use Add Attribute To Field to insert {categories.CatID_AttrID} for both attributes with “ – ” between them', 'Type the values into the title', 'Use a replacement tag <Category_CatID_AttrID />'], answer: 1, explain: 'The Header uses {categories.…} tags inserted with Add Attribute To Field; <Category_… /> tags are for item names in templates.', guide: 'bw-perspective-widgets' },
  { id: 'bw-qc-smart-008', domain: 'ba-smart', q: 'Which widget can currently be embedded in the Header widget?', options: ['Metadata', 'Discussion', 'Activity Feed', 'Team'], answer: 2, explain: 'Only the Activity Feed can be embedded; it requires Content Server Pulse to be enabled.', guide: 'bw-perspective-widgets' },
  { id: 'bw-qc-smart-009', domain: 'ba-smart', q: 'The Discussion widget’s Browse Forum option is left empty and the workspace contains two forums. Which forum is shown?', options: ['None — an error is displayed', 'The newest forum', 'Both forums alternately', 'The oldest forum'], answer: 3, explain: 'An empty option links automatically to the workspace’s forum, choosing the oldest if there are several.', guide: 'bw-perspective-widgets' },
  { id: 'bw-qc-smart-010', domain: 'ba-smart', q: 'Which two prerequisites support the Follow feature of the Discussion widget? (Choose two.)', options: ['Category inheritance enabled', 'Notifications configured', 'eLink configured', 'A slice for the workspace type'], answer: [1, 2], explain: 'As with Classic forums, Follow needs notifications and eLink set up.', guide: 'bw-perspective-widgets' },
  { id: 'bw-qc-smart-011', domain: 'ba-smart', q: 'What is the default width of the Workspaces and Configuration Volume widgets?', options: ['One third', 'Quarter', 'Full', 'Half'], answer: 1, explain: 'Both default to Quarter; Team, Metadata and Discussion default to One third.', guide: 'bw-perspective-widgets' },
  { id: 'bw-qc-smart-012', domain: 'ba-smart', q: 'Which two options belong to the Metadata widget? (Choose two.)', options: ['Group Name for grouping attributes', 'Workspace type to list', 'Theme colour group', 'Hide empty fields'], answer: [0, 3], explain: 'Metadata offers Width, Title, Hide empty fields and categories/attributes with optional group names. Workspace type belongs to the Workspaces widget; Theme to Configuration Volume.', guide: 'bw-perspective-widgets' },
  { id: 'bw-qc-smart-013', domain: 'ba-smart', q: 'A designer edits the perspective in the Code Editor view, then moves a widget in the Designer view. What happens to the manual code edits?', options: ['They are moved to a new tab', 'They are saved as a second perspective', 'They are kept and merged', 'They are undone by the Designer change'], answer: 3, explain: 'Designer changes undo manual Code Editor changes; code edits are not reflected in the Designer view.', guide: 'bw-perspectives' },
  { id: 'bw-qc-smart-014', domain: 'ba-smart', q: 'How do you give a newly added perspective tab its name?', options: ['Double-click the tab and enter it in the Multilingual Values dialog', 'Rename it in the Perspectives volume', 'Set it on the General tab', 'Tabs take the first widget’s title'], answer: 0, explain: 'Tab names are multilingual values edited by double-clicking the tab.', guide: 'bw-perspectives' },
  { id: 'bw-qc-smart-015', domain: 'ba-smart', q: 'Where are business workspace perspectives stored?', options: ['In the Document Templates volume', 'In the Perspectives volume, in a folder named after the workspace type', 'Inside each workspace', 'In the Slice Folder'], answer: 1, explain: 'Enterprise ▸ Business Workspaces ▸ Perspectives holds them, organised per workspace type; they can be added to a Transport Warehouse.', guide: 'bw-perspectives' },
  { id: 'bw-qc-smart-016', domain: 'ba-smart', q: 'What does the Configuration Volume widget give Smart View users with sufficient rights?', options: ['Server configuration settings', 'The search configuration', 'Access to configuration volumes such as Document Templates', 'A list of workspace types'], answer: 2, explain: 'It provides access to configuration volumes like the Document Templates volume; its options are Width and Theme.', guide: 'bw-perspective-widgets' },

  // ------------------------------------------------------------ more multiple-response
  { id: 'bw-qc-types-017', domain: 'ws-types', q: 'Which two things happen when OpenText’s recommendation is followed and both category and classification inheritance are disabled on a template? (Choose two.)', options: ['The workspace itself loses its category', 'Workspaces can no longer be found by search', 'Documents added in new workspaces no longer receive a copy of the workspace category', 'Sub-items do not pick up the workspace classification automatically'], answer: [2, 3], explain: 'Only the copying to sub-items stops; the workspace keeps its category, and child-item indexing keeps documents findable by workspace data.', guide: 'bw-create-template' },
  { id: 'bw-qc-roles-014', domain: 'ws-roles', q: 'A workspace is created from a template that has the roles Template Administrator, Buyer (Team Lead) and Quality Engineer, with the group “Purchasing Admins” in Template Administrator and “Finance Reviewers” in Quality Engineer. Which two end up in the new workspace’s team? (Choose two.)', options: ['A copy of the template’s Specific tab', 'The Buyer role', 'The Quality Engineer role with Finance Reviewers as participant', 'The Template Administrator role with Purchasing Admins'], answer: [1, 2], explain: 'All roles and template participants are copied except the Template Administrator role.', guide: 'bw-team-roles' },
  { id: 'bw-qc-baroles-013', domain: 'ba-roles', q: 'Which two statements about workspace hierarchies are correct? (Choose two.)', options: ['The parent template defines which workspace kinds may be created inside it', 'Workspace kinds in a hierarchy are identified by their classifications', 'A child workspace automatically grants its members access to the parent', 'Hierarchies are defined in Perspective Manager'], answer: [0, 1], explain: 'Hierarchies are set in the document templates and use classifications to identify workspace kinds; access does not flow from child to parent.', guide: 'bw-workspace-hierarchies' },
  { id: 'bw-qc-using-016', domain: 'ws-using', q: 'Which two actions are performed on each business workspace after creation rather than on the template? (Choose two.)', options: ['Adding the people who work on this particular object to roles', 'Defining which roles exist', 'Attaching the workspace category', 'Email-enabling the email folder'], answer: [0, 3], explain: 'Each workspace needs its own email alias and its own team members; roles and the category are set once on the template.', guide: 'bw-creation-wizard' },
  { id: 'bw-qc-search-014', domain: 'ba-search', q: 'Which two tasks in the workspace search set-up need system-administration access according to the course? (Choose two.)', options: ['Choosing Show check boxes in Make Custom View Search', 'Adding a Custom View Search widget to a tab', 'Making the XECMWkspLinkRefTypeID region queryable', 'Monitoring the Interchange Pools in the Enterprise Data Flow Manager'], answer: [2, 3], explain: 'Region settings and data-flow monitoring are system-level pages; building custom views and perspectives is business administration.', guide: 'bw-search-config' },
  { id: 'bw-qc-smart-017', domain: 'ba-smart', q: 'A new workspace perspective opens with a sample layout. Which two statements about it are true? (Choose two.)', options: ['It uses the landing page of the user', 'It is tied to the workspace type by a rule', 'It contains a Documents tab with the Node Browsing Table', 'It contains no widgets until you add them'], answer: [1, 2], explain: 'The sample has a rule for the type, a Header, an Overview tab (Team, Metadata, Discussion) and a Documents tab (Node Browsing Table).', guide: 'bw-perspectives' },
];
